from ortools.constraint_solver import pywrapcp,routing_enums_pb2
D=[[0,4,8,6,7],[4,0,5,3,6],[8,5,0,4,3],[6,3,4,0,2],[7,6,3,2,0]];dem=[0,2,2,3,1];m=pywrapcp.RoutingIndexManager(5,2,0);r=pywrapcp.RoutingModel(m);dc=r.RegisterTransitCallback(lambda a,b:D[m.IndexToNode(a)][m.IndexToNode(b)]);r.SetArcCostEvaluatorOfAllVehicles(dc);q=r.RegisterUnaryTransitCallback(lambda a:dem[m.IndexToNode(a)]);r.AddDimensionWithVehicleCapacity(q,0,[4,4],True,'Capacity');p=pywrapcp.DefaultRoutingSearchParameters();p.first_solution_strategy=routing_enums_pb2.FirstSolutionStrategy.PATH_CHEAPEST_ARC;print(bool(r.SolveWithParameters(p)))
